# Fit the eight accepted C24 ongoing-campaign sensitivity models.
.root <- Sys.getenv("REPLICATION_ROOT", unset=""); if(!nzchar(.root)){.a<-grep("^--file=",commandArgs(FALSE),value=TRUE);.root<-file.path(dirname(normalizePath(sub("^--file=","",.a[1]))),"..","..")}
source(file.path(.root,"code","R","_table_helpers.R")); P<-replication_bootstrap(); source(file.path(P$code,"_robustness_helpers.R"))
D<-prepare_robustness_data(P);df<-D$df;df$concession_resolved<-ifelse(df$ongoing==1,NA,df$concession);df$success3_v2<-ordered(ifelse(df$ongoing==1,1,as.integer(as.character(df$success3))))
mods<-list(list("S1","S5","fdiin_c","FDI","full"),list("S2","S6","trade_c","Trade","full"),list("S3","S7","lnaid_c","Aid","reduced"),list("S4","S8","iodonor_c","IODonor","reduced"));rows<-list();models<-list()
for(s in mods){ctrl<-if(s[[5]]=="full")"nonviolent_camp+goals+v2csreprss+lngdp+lnpop+colonized_english+lnlengthofcam+lnnum_image_sum" else "nonviolent_camp+REGCHANGE+v2csreprss+lngdp+lnlengthofcam+lnnum_image_sum";ff<-as.formula(paste("concession_resolved~eng_c*",s[[3]],"+",ctrl));fb<-as.formula(paste("success3_v2~eng_c*",s[[3]],"+",ctrl));mf<-fit_firth(ff,df);mb<-safe_bracl(fb,df);models[[s[[1]]]]<-mf;models[[s[[2]]]]<-mb;rows[[length(rows)+1]]<-long_logistf(mf,s[[1]],s[[4]],"concession_resolved");rows[[length(rows)+1]]<-long_bracl(mb,s[[2]],s[[4]],sum(complete.cases(df[,all.vars(fb)])),"success3_v2 (ongoing=limited)")}
out<-dplyr::bind_rows(rows);out$Fit_Status<-NULL;out$.order<-match(out$Model,paste0("S",1:8));out<-out[order(out$.order,seq_len(nrow(out))),];out$.order<-NULL;if(nrow(out)!=96L)stop("C24 long results must have 96 rows; found ",nrow(out),call.=FALSE)
write.csv(out,file.path(P$estimates,"appendix_ongoing_sensitivity_results.csv"),row.names=FALSE,na="");saveRDS(models,file.path(P$cache,"ongoing_models.rds"))
